mapper.select:
SELECT m.id, NULL AS user_id, m.title, m.content, m.attachment_urls AS attachmentUrls, m.type, NULL AS status, NULL AS read_time, m.sender_id, m.sender_name, m.create_time, m.update_time, COUNT(u.id) AS recipientCount, SUM(CASE WHEN u.status = 1 THEN 1 ELSE 0 END) AS readCount FROM sys_notification_msg m LEFT JOIN sys_notification_user u ON u.notification_id = m.id
AND (m.is_deleted = 0 OR m.is_deleted IS NULL)
AND m.sender_id = #{query.senderId}
AND m.title LIKE CONCAT('%', #{query.title}, '%')
AND m.type = #{query.type}
AND m.create_time >= #{query.startTime}
AND m.create_time <= #{query.endTime}
GROUP BY m.id ORDER BY m.create_time DESC
